t = int(input())

def solve():
	n = int(input())
	res = [[] for _ in range(n)]
	for i in range(n):
		s = input()
		res[i].append(i + 1)
		for (j, c) in enumerate(s):
			if c == '1':
				res[j].append(i + 1)
	for x in res:
		print(len(x), end=' ')
		print(' '.join(map(str, x)))
for i in range(t):
	solve()
